class Solution {
public:
    int idx;
    string s;

    bool parse() {
        char c = s[idx];
        if (c == 't') { idx++; return true; }
        if (c == 'f') { idx++; return false; }
        if (c == '!') return parseNot();
        if (c == '&') return parseAnd();
        return parseOr();
    }

    bool parseNot() {
        idx += 2; // skip '!' and '('
        bool val = parse();
        idx++; // skip ')'
        return !val;
    }

    bool parseAnd() {
        idx += 2; // skip '&' and '('
        bool result = parse();
        while (s[idx] == ',') {
            idx++; // skip ','
            result &= parse();
        }
        idx++; // skip ')'
        return result;
    }

    bool parseOr() {
        idx += 2; // skip '|' and '('
        bool result = parse();
        while (s[idx] == ',') {
            idx++; // skip ','
            result |= parse();
        }
        idx++; // skip ')'
        return result;
    }

    bool parseBoolExpr(string expression) {
        s = expression;
        idx = 0;
        return parse();
    }
};
